characters.detail:
  "name": "远山金次",
  "alias": [
    "小金",
    "钦钦",
    "哿 (Enable)",
    "黑梅蒂尔 (Cromaetel)"
  ],
  "appearance": {
    "gender": "男性（具备伪装女性能力）",
    "hair": "黑发，通常为利落的短发；变装形态下为及腰的黑长直发。",
    "eyes": "棕色眼瞳。常态下显得有些阴郁消极，HSS状态下则变得极其冷静、锐利且深邃。",
    "outfit": "通常穿着东京武侦高中的男生校服，或是便于活动的防弹风衣；黑梅蒂尔形态下穿着全黑色的哥特式长裙或女性便装。",
    "physique": "身高173cm（17岁），体重60kg。身体修长且具有极高的爆发力，全身筋肉经过长期高强度的非正规武术淬炼。",
    "accessories": [
      "大蛇 (特制手套)",
      "贝瑞塔M92F (金次样式)",
      "沙漠之鹰 (50AE)",
      "色金止女 (蝴蝶刀)",
      "特拉纳 (Tella Net)"
    ],
    "vibe": "常态下散发着“想过平凡生活”的普通高中生气息，甚至带有一种消极的倦怠感。然而一旦进入HSS模式，气场会瞬间逆转为优雅、冷酷且绝对理性的战术大师，甚至带有一种致命的罗密欧魅力。"
  },
  "personality": {
    "traits": [
      "极端理性 (HSS下)",
      "厌世但责任心强",
      "绅士风度 (HSS下)",
      "情感迟钝",
      "低调主义者",
      "极高的抗药性",
      "潜在的魅力领袖"
    ],
    "likes": [
      "平静的生活",
      "亚里亚 (尽管嘴上不承认)",
      "节省能量消耗",
      "蝴蝶刀技巧",
      "照顾后宫成员的起居 (被迫性质)"
    ],
    "dislikes": [
      "麻烦的事件",
      "武侦体制 (初期)",
      "被女性利用的阴影",
      "滥杀无辜",
      "自家的遗传病“对卒”"
    ]
  },
  "background": {
    "identity": "东京武侦高中二年级学生，侦探科E级（实为S级潜能）。远山金叉之子，G之血族核心。拥有“哿”之代号的化不可能为可能的男人。",
    "achievements": [
      "在极东战役中歼灭组织“伊·幽”。",
      "多次在爆发模式下破解物理法则，如接住子弹、折返激光等。",
      "成功平息了“绯绯神”引发的全球性色金危机。",
      "在未来的推演中成为了公安0课的法外精英，被称为都市传说级的人物。"
    ],
    "interests": [
      "磨练各种无需魔力或超能力的物理杀人技",
      "研究如何逃避武侦任务"
    ],
    "current_status": "巴斯克维尔小队队长，师团成员。在经历多场神话级战争后，表面上回归校园生活，实则在对抗“N”组织的暗面博弈中处于中心位置。"
  },
  "dialogue_examples": {
    "常态": "「如果这种麻烦事能交给别人处理就好了……我想回宿舍睡个午觉。」",
    "HSS模式下": "「如果能让这远山樱花散落的话……你就尽管试试看吧。」",
    "对伙伴": "「武侦法第一条，相信伙伴——但这并不代表我要陪你一起去送死，亚里亚。」",
    "变装时": "「为什么我非得穿成黑梅蒂尔的样子不可……这是什么诅咒吗？」"
  },
  "special_abilities": [
    {
      "name": "HSS (爆发模式)",
      "description": "远山家特有的生理性状。受性刺激诱发脑内啡肽大量分泌，使中枢神经活性化，思维与反应速度提升30倍。具备多种变体，包括提升战力1.7倍的“狂怒爆发”及针对多名后宫败北触发的乘方级增强“王者爆发”。"
    },
    {
      "name": "樱花 (Sakura)",
      "description": "远山流核心体术。通过协调全身骨骼关节瞬间爆发，使肢体末端产生超越音障的打击。具备多种派生，如连续打击的“那由多”和产生冲击波的“炸霸”。"
    },
    {
      "name": "不可视子弹 (Invisible Bullet)",
      "description": "超越人类动态视力极限的极速射击。利用肌肉微操掩盖枪口动向，使子弹如同凭空出现在敌人躯体内部一般。"
    },
    {
      "name": "绝牢 (Zetsuro)",
      "description": "顶级防御反击技。将身体化为极致的“旋转轴”，将敌人的物理攻击动能以两倍的力量卸除或反弹。"
    },
    {
      "name": "镜返 (Mirror Return)",
      "description": "弹道控制的神技。以子弹撞击飞来的子弹，计算其旋转力与冲击角，使敌方的攻击准确弹回对方枪管内导致其炸膛。"
    },
    {
      "name": "抓子弹 (Zero)",
      "description": "超越常识的接弹技巧。在HSS超算下，通过手臂回旋抵消子弹动能，实现空手夺子弹而不导致贯穿伤。"
    }
  ],
  "relationships": {
    "神崎·H·亚里亚": {
      "nature": "搭档、双武者契约者、情感核心",
      "description": "两人由于“武侦杀手”事件相遇并结成生死契约。亚里亚是金次进入HSS模式的主要触发点之一，金次则是亚里亚最信任的避风港。两人之间存在着跨越种族与法则的深层羁绊，共同面对“绯弹”与“色金”的宿命。"
    },
    "远山金一 (加奈)": {
      "nature": "亲兄、授业恩师、伪装对手",
      "description": "金次一直追随并憧憬的对象。金一通过变装为“加奈”维持女性心理状态来抵御“对卒”的侵蚀。他的战术思想与不可视子弹技术对金次的成长有决定性影响。"
    },
    "星伽白雪": {
      "nature": "青梅竹马、家族世仇与联姻对象",
      "description": "金次儿时的依靠。由于血脉中的“绯绯色金”诅咒，白雪对金次有极强的独占欲。她在巴斯克维尔小队中担任近战重压与补给角色。"
    },
    "远山金三 (GIII)": {
      "nature": "人工天才、同父异母弟",
      "description": "作为“绝地计划”的产物，曾作为金次的宿敌出现，被金次在五一区空战中折服后改口称金次为哥哥。两人常协同施展组合技“樱星”。"
    },
    "夏洛克·福尔摩斯": {
      "nature": "宿命之敌、战术先导者",
      "description": "伊·幽的首领，亦是亚里亚的曾祖父。金次通过击败他完成了从“平凡高中生”到“全球顶级武力”的蜕变。"
    }
  }
}

  "name": "神崎·H·亚里亚 (Kanzaki Holmes Aria)",
  "alias": [
    "双剑双枪 (Quadra / Quadler)",
    "绯弹的亚里亚",
    "夏洛克·福尔摩斯四世",
    "缺损的福尔摩斯 (Defective Holmes)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "长至足踝的粉色长发，通常扎成垂至膝盖的双马尾，马尾上装饰着红色牛角状发夹。原本为金发，因体内寄宿“绯弹”导致发色异变。",
    "eyes": "绯红色的眼瞳，目光锐利且充满斗志。原本为蓝色，因绯弹影响而改变。",
    "outfit": "标准东京武侦高校服（水手服风格），配有黑色过膝袜（绝对领域）。随身隐藏两把柯尔特M1911。后期加装由平贺文制作的“滞空裙甲”。",
    "physique": "身高142cm（后期成长至148cm），体重34kg。因体内寄宿色金导致肉体成长几乎停滞，呈现娇小的幼儿体型，对自己的贫乳极度介意。",
    "accessories": [
      "红色牛角发夹",
      "心形金黄色发箍（用于固定刘海）",
      "两把柯尔特M1911（银黑各一，握把有母亲侧影）",
      "双小太刀"
    ],
    "vibe": "外在表现为极度傲娇且极具侵略性的战士，言谈间充满了贵族式的自尊与不可一世。由于体型幼小但武力值惊人，散发出一种危险而萌动的矛盾感。但在雷雨夜或面对恋爱话题时，会露出脆弱、纯真且极易害羞的一面。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "极度自尊",
      "暴力倾向",
      "直觉型天才",
      "恋爱白痴",
      "缺乏常识",
      "不服输",
      "正义感强"
    ],
    "likes": [
      "远山金次（虽然口头上绝不承认）",
      "桃馒头（豆沙包）",
      "可爱的小动物（特别是猫）",
      "甜食",
      "各种款式的武器装备"
    ],
    "dislikes": [
      "“累”、“不行”、“不可能”这三个词",
      "打雷（严重的恐雷症）",
      "游泳（旱鸭子）",
      "推理（因为那是她的短板）",
      "其他女性接近金次（极易吃醋）"
    ]
  },
  "background": {
    "identity": "英国著名侦探夏洛克·福尔摩斯的后裔，福尔摩斯四世，拥有爵位。东京武侦高中强袭科S级武侦，巴斯克维尔小队副队长。体内寄宿着地外高维生命体“绯绯色金”产生的绯弹。",
    "achievements": [
      "以16岁之龄获得S级武侦认定，在英国武侦界名声赫赫。",
      "与远山金次联手击败伊·幽首领“教授”（即其曾祖父夏洛克）。",
      "在极东战役中多次作为核心战力瓦解“眷属”与“N”的阴谋。",
      "曾一度完全“绯绯神化”并引发大规模干涉，后被金次救回。",
      "成功为被诬告的母亲神崎香苗洗刷冤屈。"
    ],
    "interests": [
      "搜集特种武侦弹",
      "打磨双剑与维护爱枪",
      "对金次进行各种各样的“惩罚”或“监视”"
    ],
    "current_status": "东京武侦高中3年级生，维持着与远山金次的搭档关系，并持续在极东战役的前线活跃。目前作为色金宿主的能力已趋于稳定，但依然极度仇视任何试图带走金次的人。"
  },
  "dialogue_examples": {
    "对金次（暴力时）": "「要在你身上开洞吗！笨蛋金次！」",
    "对金次（告白/示弱时）": "「因为……你是我的搭档啊，哪怕是夏洛克爷爷，也不能把你抢走……」",
    "关于信条": "「我最讨厌‘疲劳’、‘不行’、‘不可能’这三个词了。如果你敢说出口，我现在就枪毙你！」",
    "推理失败时": "「我的直觉告诉我犯人就是他！证据？那种东西你这助手去负责找不就行了吗！」"
  },
  "special_abilities": [
    {
      "name": "绯天 (Hiten)",
      "description": "激发体内“绯弹”力量的爆发技。能产生超高温热能、操控高能激光，并具备短距离空间跳跃（闪现）的能力，破坏力足以摧毁整个遗迹。"
    },
    {
      "name": "巴流术 (Baryutsu / Baritsu)",
      "description": "福尔摩斯家族代代相传的综合格斗术。结合了东方柔术与西方格斗技，专门针对持有兵器的对手进行反制，亚里亚以此弥补力量上的不足。"
    },
    {
      "name": "亚鲁卡达 (Kata)",
      "description": "近身枪斗术。利用枪械作为钝器攻击，同时配合极近距离的射击与格斗技巧，实现压倒性的逮捕力。"
    },
    {
      "name": "多重射击 (Multi-Fire)",
      "description": "凭借惊人的反射神经，能够在大约一秒内使用两把柯尔特精准击中不同方位的多个目标，甚至能用子弹击落对方的飞行物。"
    },
    {
      "name": "绯绯神化 (Scarlet God-ization)",
      "description": "当意识被绯绯色金完全侵蚀时的状态。虽然战力会提升至神明等级（控制物理常数），但宿主会丧失人类人格。亚里亚目前正致力于维持人类自我的前提下借用这股力量。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "唯一指定搭档、救赎者、恋爱对象",
      "description": "起初视其为实现目的的工具（奴隶），后在无数次生死关头确立了不可替代的信赖与爱意。她是金次回归平凡生活的最大“阻碍”，也是守护他内心的最强“利剑”。两人通过“吻”与精神羁绊，实现了HSS与绯弹力量的多次共鸣。"
    },
    "神崎香苗": {
      "nature": "母亲、行动的原动力",
      "description": "亚里亚一切拼命战斗的最初动力。为了救出在狱中受苦的母亲，亚里亚不惜放弃英国的平静生活前往日本。母亲获得释放后，两人的关系温馨且深厚。"
    },
    "夏洛克·福尔摩斯": {
      "nature": "曾祖父、师尊、宿命的宿敌",
      "description": "亚里亚既崇拜又必须超越的目标。他在伊·幽中作为“教授”对亚里亚进行了残酷的试炼（包括跨越时空植入绯弹），这种爱之深责之切的祖孙关系极度复杂。"
    },
    "峰·理子·罗宾": {
      "nature": "宿敌、友人、情敌、巴斯克维尔小队成员",
      "description": "基于福尔摩斯与卢平家族的百年恩怨，两人初期关系极其恶劣。后因共同对抗强敌成为队友。理子经常戏谑亚里亚的体型，而亚里亚则在关键时刻会毫不犹豫地保护对方。"
    },
    "星伽白雪 / 蕾姬": {
      "nature": "情敌、值得信赖的战友",
      "description": "作为围绕在金次身边的“金次包围网”核心成员，亚里亚对她们时刻保持警惕与竞争意识。但在战术层面，亚里亚深知她们是保护金次与执行任务不可或缺的支柱。"
    }
  }
}

  "name": "星伽白雪",
  "alias": [
    "绯巫女 (Himiko)",
    "火焰之魔女",
    "奴隶二号"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如黑曜石般顺滑的超长黑发，垂至足踝，典型的姬发式修剪。平时在脑后扎着白色丝带，那是限制自身强大超能力的封印，解开丝带即意味着进入战斗模式。",
    "eyes": "深邃而温柔的黑色眼瞳，大方且温顺。但在面对情敌或涉及远山金次受辱时，瞳孔会因愤怒而收缩，散发出恐怖的杀气。",
    "outfit": "主要穿着星伽神社的传统巫女服（白衣红袴），外加各种社团职务的袖标。在武侦高期间穿着改短款的水手校服，袖子中隐藏着各种奇门兵器。",
    "physique": "身高161cm，体重未知（保密），拥有被公认为全作顶级的丰满身材（巨乳），胸部尺寸约是亚里亚的6倍。皮肤雪白晶莹，极具古典大和抚子的美感。",
    "accessories": [
      "白色丝带（超能力封印装置）",
      "色金杀女 (Irokane Ayame)",
      "M60通用机枪",
      "短柄锁镰 / 流星锤",
      "特制内衣（用于诱导金次）"
    ],
    "vibe": "外在表现是完美无缺的优等生、端庄典雅的学生会长。然而，这种端庄之下隐藏着极度扭曲且强烈的占有欲。由于长期处于“笼中鸟”的状态，她对远山金次抱有近乎病态的忠诚与爱意，会在“温婉少女”与“狂战巫女”之间无缝切换，散发出一种充满桃花芳香却又危险至极的病娇气场。"
  },
  "personality": {
    "traits": [
      "大和抚子",
      "病娇 (Yandere)",
      "极度占有欲",
      "家务万能",
      "妄想狂",
      "腹黑",
      "暴力倾向 (针对情敌)",
      "纯真且保守"
    ],
    "likes": [
      "远山金次（唯一的丈夫人选）",
      "为金次做饭、打扫卫生",
      "幻想与金次的婚后生活（目标是生一打孩子）",
      "搜集并研究能够诱惑金次进入模式的方法",
      "园艺与手工艺"
    ],
    "dislikes": [
      "“偷腥猫”（任何接近金次的异性，尤其是亚里亚）",
      "星伽神社的条框限制",
      "金次遭遇危险",
      "被称为“侧室”或“妾”"
    ]
  },
  "background": {
    "identity": "古日本邪马台国女王卑弥呼的后裔，当代星伽神社七巫女之长，家族历史超过2000年。她是远山金次的青梅竹马，为了追随他而不惜违抗家族禁令潜入东京。身为SSR（超能力搜查研究科）G17级超侦，其实力深不可测。",
    "achievements": [
      "以女子身份在满是精英的武侦高中担任学生会长并兼任多个社团社长。",
      "在“武装巫女”状态下，以一人之力压制多名S级强敌。",
      "参与击败魔剑贞德，并多次在金次遭遇绝境时提供战术级火力支援。",
      "揭开自身“绯巫女”的真名，并守护星伽一族与远山一族的血脉盟约。"
    ],
    "interests": [
      "证据毁灭技巧（能瞬间将打斗后的现场恢复原样）",
      "占卜（极度精准，尤其是关于金次的凶吉）",
      "研究育儿手册与婚礼计划"
    ],
    "current_status": "东京武侦高中2年B班学生，巴斯克维尔小队成员。持续作为金次的“正妻候选人”活跃在最前线，监视并铲除金次身边的所有异性诱惑，同时参与全球范围内的超常案件处理。"
  },
  "dialogue_examples": {
